We will prove  (a) and (c). The remaining parts can be deduced similarly.

First, we prove (a) for $j=n$. For every $i$ we have
\begin{align*}
[F_{\overline{n}}, e_{\overline{i}}] &= [[e_{n-1},f_{\overline{n-1}}],e_{\overline{i}}] = [e_{\overline{i}},[e_{n-1},f_{\overline{n-1}}]] = [e_{n-1}, [f_{\overline{n-1}},e_{\overline{i}}]] +  [f_{\overline{n-1}}, [e_{\overline{i}},e_{n-1}]] = [e_{n-1}, [f_{\overline{n-1}},e_{\overline{i}}]].
\end{align*}
If $i = n-2$, then we have that $[e_{n-1}, [f_{\overline{n-1}},e_{\overline{n-2}}]] = [e_{n-1}, [e_{n-1},e_{n-2}]] = 0$. If $i = n-1$, then we have that $$[e_{n-1}, [f_{\overline{n-1}},e_{\overline{n-1}}]] = [e_{n-1}, -k_{n-1}+k_n] = -[e_{n-1},k_{n-1}] + [e_{n-1},k_n] = 2e_{n-1}.$$
Otherwise, we have that $[F_{\overline{n}}, e_{\overline{i}}] = 0$.


Next we prove (a) for $j < n$. Using the relations in Proposition \ref{prop:pn}, we have that:
\begin{align*}
[F_{\overline{j}}, e_{\overline{i}}] &= [[f_{\overline{j}},f_j],e_{\overline{i}}]\\
&= [e_{\overline{i}},[f_{\overline{j}},f_j]]\\
&=   [f_{\overline{j}},[f_j, e_{\overline{i}}]] - [f_j, [e_{\overline{i}}, f_{\overline{j}}]].
\end{align*}
Note that $[F_{\overline{j}}, e_{\overline{i}}] = 0$ from above, unless $|i-j| \leq 2$. So, we need to check the three subcases $i-j = 0,1,-1$.

If $j=i$, then
\begin{align*}
[F_{\overline{i}}, e_{\overline{i}}] &=  [f_{\overline{i}},[f_i, e_{\overline{i}}]] - [f_i, [e_{\overline{i}}, f_{\overline{i}}]]\\
&=  -[f_i,  -k_i + k_{i+1}]\\
 &= 2f_i.
\end{align*}
If $i = j+1$, then
\begin{align*}
[F_{\overline{j}}, e_{\overline{j+1}}]  &= [f_{\overline{j}},[f_j, e_{\overline{j+1}}]] - [f_j, [e_{\overline{j+1}}, f_{\overline{j}}]]\\  &=  - [f_j, [f_{j+1}, f_j]] \\ &=  [f_j, [f_j, f_{j+1}]] + [f_j, [f_{j+1}, f_j]]  \\  &= 0.
\end{align*}

If $j=i+1$, then
\begin{align*}
[F_{\overline{i+1}}, e_{\overline{i}}]  &=   [f_{\overline{i+1}},[f_{i+1}, e_{\overline{i}}]] - [f_{i+1}, [e_{\overline{i}}, f_{\overline{i+1}}]]\\
 &= [f_{\overline{i+1}},[e_{\overline{i+1}}, e_{i}]] - [f_{i+1}, [e_{i+1},e_i]] \\
  &= [e_{\overline{i+1}}, [e_{i},f_{\overline{i+1}}]] - [e_i, [f_{\overline{i+1}},e_{\overline{i+1}}]] +  [e_{i+1}, [e_i,f_{i+1}]] + [e_i, [f_{i+1}, e_{i+1}]]  \\
   &= - [e_i, -k_{i+1} + k_{i+2}] - [e_i, -k_{i+1}+k_{i+2}]\\  
   &= 2e_i.
\end{align*}


Now, we prove (c). Note that $[e_i,e_{\overline{i-1}}] = 0$ for all $2\leq i \leq n$, so $[e_i, [e_i,e_{\overline{i-1}}]] = 0$. Also,
\begin{align*}
[e_i,[e_i,e_{\overline{i+1}}]] &= [e_i,[e_{\overline{i}}, f_{i+1} ]]\\
&= [e_{\overline{i}}, [f_{i+1}, e_i]] + [f_{i+1}, [e_i, e_{\overline{i}}]]\\
&=  0.
\end{align*}

\label{lem:alg}
The following relations hold in $\mathfrak{U}_q\mathfrak{p}_n$ for all $i \in I$.
\begin{itemize}
\item[(a)] $e_if_i - f_ie_i = e_{\overline{i}}f_{\overline{i}} + f_{\overline{i}} e_{\overline{i}}$,
\item[(b)] $\displaystyle \frac{2}{1+q^2}f_{\overline{i+1}}f_{i+1}f_i - f_{\overline{i+1}}f_if_{i+1} - f_{i+1}f_if_{\overline{i+1}} + q^2f_if_{i+1}f_{\overline{i+1}} = q^2q^{2k_{i+1}}f_{\overline{i}} - \frac{1-q^2}{1+q^2}f_{i+1}f_{\overline{i+1}}f_i$,
\item[(c)] $\displaystyle f_ie_i = e_if_i+q^2\frac{q^{2k_i}-q^{k_{i+1}}}{q^2-1} + (q^2-1)e_{\overline{i}}f_{\overline{i}}$.
\end{itemize}

Let $U$ be the unital associative superalgebra over $\mathbb{C}(q)$ generated by the elements $e_i, f_i, e_{\overline{i}}, f_{\overline{i}}$ for $i\in I$, $F_{\overline{i}}$ for $i\in I \cup \{ n\}$, and $q^h$ for $h\in P^{\vee}$ with defining relations given in the statement of the proposition above. 

We first note that using  (\ref{Uqpngen}) and particular choices for $i,j,k,l$ in 
 (\ref{exprel})   one can establish on a case-by-case basis all relations in the proposition. Hence, we have an associative superalgebra homomorphism $\psi: U\rightarrow \mathfrak{U}_q\mathfrak{p}_n$. The relations in (\ref{qB2}) immediately show that $\psi$ is surjective. 

It remains to show that $\psi$ is injective. For this, we prove that (\ref{exprel}) is obtained from the relations in the statement of the proposition by  considering the following 26 cases:

\begin{multicols}{4}
    \begin{enumerate}
        \item $\vert i \vert = \vert j \vert < \vert k \vert < \vert l \vert$
        \item $\vert k \vert < \vert i \vert = \vert j \vert < \vert l \vert$
        \item $\vert k \vert  < \vert l \vert < \vert i \vert = \vert j \vert $
        \item $\vert k \vert = \vert l \vert < \vert i \vert <  \vert j \vert $
        \item $\vert i \vert < \vert k \vert = \vert l \vert <\vert j \vert$
        \item $\vert i \vert <  \vert j \vert < \vert k \vert = \vert l \vert$
        \item $\vert i \vert = \vert k \vert < \vert j \vert < \vert l \vert$
        \item $\vert i \vert = \vert k \vert <\vert l \vert < \vert j \vert$
        \item $\vert i \vert < \vert k \vert <\vert l \vert = \vert j \vert$
        \item $\vert k \vert < \vert i \vert <\vert l \vert = \vert j \vert$
        \item $\vert k \vert < \vert l \vert =\vert i \vert < \vert j \vert$
        \item $\vert i \vert < \vert j \vert =\vert k \vert < \vert l \vert$
        \item $\vert i \vert < \vert j \vert < \vert k \vert < \vert l \vert$
        \item $\vert i \vert < \vert k \vert <\vert j \vert < \vert l \vert$
        \item $\vert i \vert < \vert k \vert <\vert l \vert < \vert j \vert$
        \item $\vert k \vert < \vert i \vert <\vert j \vert < \vert l \vert$
        \item $\vert k \vert < \vert i \vert <\vert l \vert < \vert j \vert$
        \item $\vert k \vert < \vert l \vert <\vert i \vert < \vert j \vert$
        \item $\vert k \vert = \vert l \vert <\vert i \vert = \vert j \vert$
        \item $\vert i \vert = \vert j \vert < \vert k \vert = \vert l \vert$
        \item $\vert i \vert = \vert k \vert < \vert j \vert = \vert l \vert$
        \item $\vert i \vert = \vert j \vert = \vert k \vert < \vert l \vert$
        \item $\vert k \vert < \vert i \vert = \vert j \vert = \vert l \vert$
        \item $\vert i \vert = \vert k \vert = \vert l \vert < \vert j \vert$
        \item $\vert i \vert < \vert j \vert = \vert k \vert = \vert l \vert$
        \item $\vert i \vert = \vert j \vert = \vert k \vert = \vert l \vert$
    \end{enumerate}
    \end{multicols}

The verification in each case uses the relations \eqref{eq-induction-1} and \eqref{eq-induction-2} and appropriate induction. In fact, for some cases, we apply useful  identities that follow from  \eqref{eq-induction-1} and \eqref{eq-induction-2}, see Lemma \ref{lem:alg} below. For example, in Case 21 we use Lemma \ref{lem:alg}(c). For reader's convenience, we write detailed proofs for cases 2 and 25. The remaining cases are established using analogous reasoning. 

\noindent{\it Case 2.} Suppose that $\vert k \vert < \vert i \vert = \vert j \vert < \vert l \vert$ in (\ref{exprel}). We prove that 
\begin{align*}
 (-1)^{(p(i)+p(j))(p(k)+p(\ell))}t_{ij}t_{k\ell} - t_{k\ell}t_{ij} = 0
\end{align*}
is obtained from some of the relations in the proposition applying  induction on  $|\ell| - |i|$ first, and  then induction on $|i| - |k|$. We consider only the case of when $i=-j >0$ and $k,\ell > 0$ as the other cases follow similarly. 

We start with the base case of the first induction, i.e.,  $\ell = i+1$. For the base case of the second induction, we have $i = k+1$. Then
\begin{small}
\begin{align*}
t_{k+1,-k-1}t_{k,k+2} - t_{k,k+2}t_{k+1,-k-1} &= -\frac{(q-q^{-1})^2}{2} \left( F_{\overline{k+1}}q^{-k_{k+1}}(f_{k+1}f_k-f_kf_{k+1})-q^{-k_{k+1}}(f_{k+1}f_k-f_kf_{k+1})F_{\overline{k+1}} \right)\\
&= -\frac{(q-q^{-1})^2}{2}q^{-k_{k+1}}[q^{-2}F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1})-(f_{k+1}f_k-f_kf_{k+1})F_{\overline{k+1}}]\\
&= -\frac{(q-q^{-1})^2}{2}q^{-k_{k+1}}[F_{\overline{k+1}}f_{k+1}f_k-F_{\overline{k+1}}f_kf_{k+1} -f_{k+1}f_kF_{\overline{k+1}}+f_kf_{k+1}F_{\overline{k+1}} \\ &+ (q^{-2}-1)F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1})]\\
&= -\frac{(q-q^{-1})^2}{2}q^{-k_{k+1}}[q^{-1}f_{k+1}F_{\overline{k+1}}f_k-F_{\overline{k+1}}f_kf_{k+1} -f_{k+1}f_kF_{\overline{k+1}}+qf_kF_{\overline{k+1}}f_{k+1}\\ &+ (q^{-2}-1)F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1})]\\
&= -\frac{(q-q^{-1})^2}{2}q^{-k_{k+1}}[f_{k+1}(q^{-1}F_{\overline{k+1}}f_k - f_kF_{\overline{k+1}})-q(q^{-1}F_{\overline{k+1}}f_k - f_kF_{\overline{k+1}})f_{k+1}\\ &+ (q^{-2}-1)F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1})]\\
&= -\frac{(q-q^{-1})^2}{2}q^{-k_{k+1}}[2f_{k+1}q^{k_{k+1}}f_{\overline{k}}-2qq^{k_{k+1}}f_{\overline{k}}f_{k+1} + (q^{-2}-1)F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1})]\\
&= -\frac{(q-q^{-1})^2}{2}q^{-k_{k+1}}[2qq^{k_{k+1}}(f_{k+1}f_{\overline{k}}-f_{\overline{k}}f_{k+1}) + (q^{-2}-1)F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1})]\\
&= -\frac{(q-q^{-1})^2}{2}q^{-k_{k+1}}[(1-q^{-2})F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1}) +  (q^{-2}-1)F_{\overline{k+1}}(f_{k+1}f_k-f_kf_{k+1})]\\
&= 0.
\end{align*}
\end{small}
The induction step for the second induction  ($i - k \geq 2$) is established as follows:
\begin{align*}
t_{i,-i}t_{k,i+1} - t_{k,i+1}t_{i,-i} 
&= -\frac{q-q^{-1}}{2}[F_{\overline{i}}q^{-k_{k+1}}(f_kt_{k+1,i+1}-t_{k+1,i+1}f_k)-t_{k,i+1}F_{\overline{i}}]\\   
&= -\frac{q-q^{-1}}{2}[q^{-k_{k+1}}F_{\overline{i}}(f_kt_{k+1,i+1}-t_{k+1,i+1}f_k)-t_{k,i+1}F_{\overline{i}}]\\    
&= -\frac{q-q^{-1}}{2}[q^{-k_{k+1}}(f_kt_{k+1,i+1}-t_{k+1,i+1}f_k)F_{\overline{i}}-t_{k,i+1}F_{\overline{i}}]\\   
&= -\frac{q-q^{-1}}{2}[t_{k,i+1}F_{\overline{i}}-t_{k,i+1}F_{\overline{i}}]\\    
&= 0.
\end{align*}

For the induction step of the first induction ($\ell - i \geq 2$) we proceed as follows:
\begin{align*}
t_{i,-i}t_{k\ell} - t_{k\ell}t_{i,-i} &= -\frac{q-q^{-1}}{2}[F_{\overline{i}}q^{-k_{\ell-1}}(f_{\ell-1}t_{k,\ell-1}-t_{k,\ell-1}f_{\ell-1})-q^{-k_{\ell-1}}(f_{\ell-1}t_{k,\ell-1}-t_{k,\ell-1}f_{\ell-1})F_{\overline{i}}]\\
&= -\frac{q-q^{-1}}{2}[q^{-k_{\ell-1}}F_{\overline{i}}(f_{\ell-1}t_{k,\ell-1}-t_{k,\ell-1}f_{\ell-1})-q^{-k_{\ell-1}}(f_{\ell-1}t_{k,\ell-1}-t_{k,\ell-1}f_{\ell-1})F_{\overline{i}}]\\
&= -\frac{q-q^{-1}}{2}[q^{-k_{\ell-1}}(f_{\ell-1}t_{k,\ell-1}-t_{k,\ell-1}f_{\ell-1})F_{\overline{i}}-q^{-k_{\ell-1}}(f_{\ell-1}t_{k,\ell-1}-t_{k,\ell-1}f_{\ell-1})F_{\overline{i}}]\\
&= 0
\end{align*}

\noindent{\it Case 25.} Suppose that $\vert i \vert < \vert j \vert = \vert k \vert = \vert l \vert$ in (\ref{exprel}). We prove that 
\begin{align*}
0 =(-1)^{(p(i)+p(j))(p(j)+p(k))}q^{\text{sgn}(j)}t_{ij}t_{kj} - t_{kj}t_{ij}
\end{align*}
for $j=\ell$, and
\begin{align*}
0=(-1)^{(p(i)+p(j))(p(j)+p(k))}q^{\text{sgn}(j)}t_{ij}t_{k,-j} - t_{k,-j}t_{ij} + (-1)^{p(i)}\delta_{j>0}(q-q^{-1})t_{i,-j}t_{kj}
\end{align*}
for $j=-\ell$, using some of the relations in the proposition. We proceed by  induction on $|j| - |i|$ and  consider only the case $i > 0$ and $j=k > 0$ as the other cases follow similarly. 

For the base case $j = i + 1$, the relations
\begin{align*}
qt_{i,i+1}t_{i+1,i+1} = t_{i+1,i+1}t_{i,i+1}
\end{align*}
when $j=\ell$, and 
\begin{align*}
qt_{i,i+1}t_{i+1,-i-1} - t_{i+1,-i-1}t_{i,i+1} = -(q-q^{-1})t_{i,-i-1}t_{i+1,i+1}
\end{align*}
when $j=-\ell$, follow from the relations $q^{k_{i+1}}f_{i} = qf_{i}q^{k_{i+1}}$ and $f_iF_{\overline{i+1}} - q^{-1}F_{\overline{i+1}}f_i=-2q^{k_{i+1}}f_{\overline{i}} $.  For the induction step ($j - i \geq 2$) we have:
\begin{align*}
qt_{ij}t_{jj} 
&= qq^{-k_{i+1}}(f_{i}t_{i+1,j}-t_{i+1,j}f_i)q^{k_j}\\
&= q^{k_j}q^{-k_{i+1}}(f_{i}t_{i+1,j}-t_{i+1,j}f_i)\\
&= t_{jj}t_{ij}
\end{align*}
for $j=\ell$, and
\begin{align*}
qt_{ij}t_{j,-j} &= -q\frac{q-q^{-1}}{2}q^{-k_{i+1}}(f_{i}t_{i+1,j}-t_{i+1,j}f_i)F_{\overline{j}}\\
&= -q\frac{q-q^{-1}}{2}q^{-k_{i+1}}f_{i}t_{i+1,j}F_{\overline{j}}+q\frac{q-q^{-1}}{2}q^{-k_{i+1}}t_{i+1,j}f_iF_{\overline{j}}\\
&= -\frac{q-q^{-1}}{2}q^{-k_{i+1}}f_{i}(F_{\overline{j}}t_{i+1,j}+2t_{i+1,-j}q^{k_j})+\frac{q-q^{-1}}{2}q^{-k_{i+1}}(F_{\overline{j}}t_{i+1,j}+2t_{i+1,-j}q^{k_j})f_i\\
&= \frac{q-q^{-1}}{2}q^{-k_{i+1}}F_{\overline{j}}(f_it_{i+1,j}-t_{i+1,j}f_i) -(q-q^{-1})q^{-k_{i+1}}(f_it_{i+1,-j}-t_{i+1,-j}f_i )q^{k_j}\\
&= \frac{q-q^{-1}}{2}F_{\overline{j}}q^{-k_{i+1}}(f_it_{i+1,j}-t_{i+1,j}f_i) -(q-q^{-1})q^{-k_{i+1}}(f_it_{i+1,-j}-t_{i+1,-j}f_i )q^{k_j}\\
&= t_{j,-j}t_{ij} -(q-q^{-1})t_{i,-j}t_{jj}
\end{align*}
for $j=-\ell$.

\label{lem:tridecomp}
Let $\mathfrak{U}_q^{\geq 0}$ (respectively, $\mathfrak{U}_q^{\leq 0}$) be generated by $\mathfrak{U}_q^0$ and $\mathfrak{U}_q^+ $ (respectively,  $\mathfrak{U}_q^0$ and $\mathfrak{U}_q^-$). Then the following $\mathbb{C}(q)$-linear isomorphisms hold.
\begin{align*}
\mathfrak{U}_q^{\geq 0} \cong \mathfrak{U}_q^0 \otimes \mathfrak{U}_q^+, \hspace{30pt} \mathfrak{U}_q^{\leq 0} \cong \mathfrak{U}_q^- \otimes \mathfrak{U}_q^0.
\end{align*}

We will prove the second isomorphism. Let $\{f_\zeta \mid \zeta \in \Omega\}$ be a basis of $\mathfrak{U}_q^-$ consisting of monomials in $f_i$'s, $f_{\overline{i}}$'s, and $F_{\overline{j}}$'s ($1\leq i \leq n-1$, $1\leq j \leq n$), with $\Omega$ being an index set. Consider the map $\varphi: \mathfrak{U}_q^- \otimes \mathfrak{U}_q^0 \rightarrow \mathfrak{U}_q^{\leq 0} $ defined by $\varphi(f_\zeta \otimes q^h) = f_\zeta q^h$. The defining relations of $\mathfrak{U}_q\mathfrak{p}_n$ imply that $f_\zeta q^h$ span $\mathfrak{U}_q^{\leq 0} $, so $\varphi$ is surjective. It remains to show that the set $\{f_\zeta q^h \mid \zeta \in \Omega, h\in P^\vee\}$ is linearly independent over $\mathbb{C}(q)$.



Suppose 
\begin{align*}
\sum_{\substack{\zeta\in\Omega \\ h\in P^\vee}} C_{\zeta, h} f_\zeta q^h = 0,
\end{align*}
for some  $C_{\zeta, h} \in \mathbb{C}(q)$.  Then
\begin{align*}
\sum_{\alpha\in Q_-} \left(\sum_{\substack{\deg f_\zeta = \alpha \\ h\in P^\vee}} C_{\zeta, h} f_\zeta q^h\right) = 0.
\end{align*}
Write  $\displaystyle \alpha = -\sum_{i=1}^{n-1}(m_i\alpha_i+n_i\gamma_i) - \sum_{i=1}^{n}r_i\beta_i$, for $m_i,n_i, r_i\in \mathbb{Z}_{\geq 0}$, and let $\displaystyle h_\alpha = \sum_{i=1}^{n-1}(m_i+n_i)k_{i+1} + \sum_{i=1}^{n}r_ik_{i}$ and  $\displaystyle h_\alpha^\prime = \sum_{i=1}^{n-1}(m_i+n_i)k_{i} +r_ik_{i}$. From $\displaystyle \mathfrak{U}_q\mathfrak{p}_n = \bigoplus_{\alpha\in Q} (\mathfrak{U}_q)_\alpha$, we have that, for each $\alpha\in Q_-$,
\begin{align}\label{sum2}
\sum_{\substack{\deg f_\zeta = \alpha \\ h\in P^\vee}} C_{\zeta, h} f_\zeta q^h = 0.
\end{align}
Since $f_\zeta$ is a monomial in $f_i$'s, $f_{\overline{i}}$'s, and $F_{\overline{i}}$'s, we have

\begin{align*}
\Delta(f_\zeta) = f_\zeta \otimes q^{h_{\alpha}} + \ldots + q^{h_{\alpha}^\prime} \otimes f_\zeta.
\end{align*}

Hence, the degree $(\alpha, 0)$ term in the decomposition of  $\Delta(f_\zeta)$ equals $ f_\zeta \otimes q^{h_{\alpha}}$. Applying the comultiplication to (\ref{sum2}) gives

\begin{align*}
\sum_{\substack{\deg f_\zeta = \alpha \\ h\in P^\vee}} C_{\zeta, h} ( f_\zeta q^{h} \otimes q^{h+h_{\alpha}} + \hdots + q^{h+h_{\alpha}^\prime} \otimes f_\zeta q^{h} ) = 0.
\end{align*}

Collecting the terms of degree $(\alpha, 0)$ gives that

\begin{align*}
\sum_{\substack{\deg f_\zeta = \alpha \\ h\in P^\vee}} C_{\zeta, h}  (f_\zeta q^{h} \otimes q^{h+h_{\alpha}})= 0.
\end{align*}

Since for every $\alpha$, the set $\{q^{h+h_{\alpha}} \mid h \in P^\vee\}$ is linearly independent, we have that, for all $h\in P^\vee$: 

\begin{align*}
& \sum_{\substack{\deg f_\zeta = \alpha }} C_{\zeta, h} f_\zeta q^{h} = 0.
\end{align*}

Due to the linear independence of $f_\zeta$, we conclude that $C_{\zeta, h} =0$ for all $\zeta, h$,  as desired.

\label{thm:tridecomp} There is a $\mathbb{C}(q)$-linear isomorphism 
\begin{align*}
\mathfrak{U}_q(\mathfrak{p}_n) \cong \mathfrak{U}_q^- \otimes \mathfrak{U}_q^0 \otimes \mathfrak{U}_q^+.
\end{align*}

Let $\{f_\zeta \mid \zeta \in \Omega\}$, $\{q^h \mid h \in P^\vee\}$, and $\{e_\tau \mid \tau \in \Omega^\prime\}$ be monomial bases of $\mathfrak{U}_q^-$, $\mathfrak{U}_q^0$, and $\mathfrak{U}_q^+$, respectively, where $\Omega$ is the index set as in the proof of Lemma \ref{lem:tridecomp}, and $\Omega^\prime$ is another  index set. Using the defining relations of $\mathfrak{U}_q\mathfrak{p}_n$ in Proposition \ref{prop:alg}, we can  express every monomial in $\mathfrak{U}_q(\mathfrak{p}_n)$ as a linear combination of monomials each of which has   $e_i$ and $e_{\overline{i}}$ on the right. By Lemma \ref{lem:tridecomp}, the monomials   $f_{\zeta}q^he_{\tau}$ span $\mathfrak{U}_q\mathfrak{p}_n$. Hence, it remains to show that  $f_{\zeta}q^he_{\tau}$ are linearly independent over $\mathbb{C}(q)$. 

Suppose
\begin{align*}
\sum_{\substack{\zeta\in\Omega, \tau\in \Omega^\prime \\ h\in P^\vee}} C_{\zeta, h,\tau} f_\zeta q^h e_{\tau} = 0,
\end{align*}
where $C_{\zeta, h,\tau}$ is some nonzero constant in $\mathbb{C}(q)$. Due to the $Q$-grading of $\mathfrak{U}_q\mathfrak{p}_n$, we have that, for all $\alpha \in Q$:
\begin{align} \label{sum1}
\sum_{\substack{\deg f_\zeta + \deg e_\tau = \alpha \\ h\in P^\vee}} C_{\zeta, h,\tau} f_\zeta q^h e_{\tau} = 0.
\end{align}

Define a partial ordering on $\mathfrak{h}^*$ by $\lambda \leq \mu $ if and only if $\lambda - \mu \in Q_-$ for $\lambda,\mu \in \mathfrak{h}^*$. We then choose $\gamma = \deg f_{\zeta}$ and $\beta = \deg e_{\tau}$, which are minimal and maximal, respectively, among those for which $\gamma + \beta = \alpha$ and $C_{\zeta, h, \tau} \neq 0$. If $\displaystyle \gamma = -\sum_{i=1}^{n-1}(m_i\alpha_{i}+n_i\gamma_{i}) - \sum_{i=1}^{n}r_i\beta_{i}$, set $\displaystyle h_\gamma = \sum_{i=1}^{n-1}(m_i+n_i)k_{i+1} + \sum_{i=1}^{n}r_ik_{i}$, and if $\displaystyle \beta = \sum_{i=1}^{n-1}(m^\prime_i\alpha_{i}+n^\prime_i\gamma_{i})$, set $\displaystyle h_\beta = \sum_{i=1}^{n-1}(m^\prime_ik_{i}+n^\prime_ik_{i})$, for $m_i,m^\prime_i,n_i,n^\prime_i, r_i\in \mathbb{Z}_{\geq 0}$. 


The term of degree $(0,\beta)$ in $\Delta(e_\tau)$ is $q^{h_\beta}\otimes e_{\tau}$ and the term of degree $(\gamma,0)$ in $\Delta(f_\zeta)$ is $f_{\zeta} \otimes q^{h_\gamma}$. Applying the comultiplication to the sum in (\ref{sum1}), and looking at the terms of degree $(\gamma, \beta)$, we have that
\begin{align*}
\sum_{\substack{\deg f_\zeta = \gamma \\ \deg e_\tau = \beta \\ h\in P^\vee}} C_{\zeta, h,\tau}  (f_\zeta q^{h+h_\beta} \otimes q^{h+h_{\gamma}}e_\tau)= 0.
\end{align*}

By Lemma \ref{lem:tridecomp}, the elements $f_\zeta q^h$ are linearly independent for $\zeta\in\Omega, h\in P^\vee$. Thus, for all $h\in P^\vee$, we have that

\begin{align*}
& \sum_{\substack{\deg e_\tau = \beta }} C_{\zeta, h, \tau} q^{h+h_\gamma}e_\tau = 0.
\end{align*}

Due to the linear independence of $e_\tau$, we conclude that  $C_{\zeta, h, \tau} =0$, leading to contradiction. Therefore all coefficients in \eqref{sum1} are zero.

