If $f_i^{\lambda(k_i) - \lambda(k_{i+1})+1} v \neq 0$ and $\mathfrak{U}_q^+f_i^{\lambda(k_i) - \lambda(k_{i+1})+1} v = 0$, then $f_i^{\lambda(k_i) - \lambda(k_{i+1})+1} v $ generates a nontrivial proper submodule of $V^q(\lambda)$, which would be a contradiction to the fact that $V^q(\lambda)$ is irreducible. Therefore, it is enough to show that $\mathfrak{U}_q^+f_i^{\lambda(k_i) - \lambda(k_{i+1})+1} v = 0$.

Note that for $j\neq i-1,i$, we have that
\begin{align*}
e_jf_i^{\lambda(k_i) - \lambda(k_{i+1})+1}v = f_i^{\lambda(k_i) - \lambda(k_{i+1})+1}e_j v = 0.
\end{align*} 

We next prove that  $e_jf_i^{\lambda(k_i) - \lambda(k_{i+1})+1}v = 0$ for $j=i,i-1$. In the case $j=i$, we use Lemma \ref{lem:action}(a) for $m= \lambda(k_i) - \lambda(k_{i+1})+1$:\begin{align*}
e_if_i^{(m)}v = \frac{q^{m-1+2\lambda(k_{i+1})}-q^{-m+1+2\lambda(k_i)}}{q^2-1} f_i^{(m-1)}v =0.
\end{align*}

For $j=i-1$ we apply induction on $m$. The base case $m=1$ follows from 
\begin{align*}
e_{i-1}f_iv =f_ie_{i-1}v - \frac{1-q^{-2}}{2q}q^{-k_{i}}F_{\overline{i}}(e_{\overline{i}}e_{i-1} - e_{i-1}e_{\overline{i}}) v = 0.
\end{align*}
Assume that  $e_{i-1}f_i^{ m} v =0$. Then we have 
\begin{align*}
e_{i-1}f_i^{ m+1} v &= f_ie_{i-1}f_i^{ m} v - \frac{1-q^{-2}}{2q}q^{-k_{i}}F_{\overline{i}}(e_{\overline{i}}e_{i-1} - e_{i-1}e_{\overline{i}})f_i^{ m} v \\
&=  f_ie_{i-1}f_i^{ m} v - \frac{1-q^{-2}}{2q}q^{-k_{i}}F_{\overline{i}}e_{\overline{i}}e_{i-1}f_i^{ m} v  + \frac{1-q^{-2}}{2q}q^{-k_{i}}F_{\overline{i}}e_{i-1}f_i^{ m} e_{\overline{i}}v \\
&=  \left(f_i- \frac{1-q^{-2}}{2q}q^{-k_{i}}F_{\overline{i}}e_{\overline{i}}\right)e_{i-1}f_i^{ m} v =0.
\end{align*}
Therefore, $e_jf_i^{ \lambda(k_i) - \lambda(k_{i+1})+1}v  = 0$ for all $j\in I$.

Lastly, we prove that  $e_{\overline{j}}f_i^{\lambda(k_i) - \lambda(k_{i+1})+1}v = 0$ for all $j \in I$. Note that for $j\neq i-1$,
\begin{align*}
e_{\overline{j}}f_i^{ \lambda(k_i) - \lambda(k_{i+1})+1}v = f_i^{ \lambda(k_i) - \lambda(k_{i+1})+1}e_{\overline{j}}v = 0.
\end{align*}

For $j = i-1$, using that $e_{i-1}f_i^{ m} v = 0$, we have
\begin{align*}
e_{\overline{i-1}}f_{i}^{m+1}v = f_ie_{\overline{i-1}}f_i^mv - e_{\overline{i}}e_{i-1}f_i^mv + e_{i-1}e_{\overline{i}}f_i^mv =  f_ie_{\overline{i-1}}f_i^mv.
\end{align*}
Thus we obtain $e_{\overline{i-1}}f_i^mv  = 0$ by induction on $m$. Hence, $\mathfrak{U}_q^+f_i^{\lambda(k_i) - \lambda(k_{i+1})+1} v = 0$ and the proof is complete.

