\label{thm:classicallimit} \hspace{2pt} \\ \vspace{-15pt}
\begin{itemize}
\item[(a)] The elements $\overline{e_i}$, $\overline{e_{\overline{i}}}$, $\overline{f_i}$, $\overline{f_{\overline{i}}}$, ($i\in I$) $\overline{F_{\overline{i}}}$, ($i\in I \cup \{ n\}$) and $\overline{h}$ ($h\in P^\vee$) satisfy the defining relations of $\mathfrak{U}\mathfrak{p}_n$. Moreover, there exists a  $\mathbb{C}$-superalgebra isomorphism $\varphi : \mathfrak{U}\mathfrak{p}_n \longrightarrow U_1$ and the $U_1$-module $V^1$ has a $\mathfrak{U}\mathfrak{p}_n$-module structure.
\item[(b)] For each $\mu \in P$ and $h\in P^\vee$, the element $\overline{h}$ acts on $V_\mu^1$ as scalar multiplication by $\mu(h)$. So, $V_\mu^1$ is the $\mu$-weight space of the $\mathfrak{U}\mathfrak{p}_n$-module $V^1$.
\item[(c)] As a $\mathfrak{U}\mathfrak{p}_n$-module, $V^1$ is a highest weight module with highest weight $\lambda \in P$ and highest weight vector $\overline{v}$.
\end{itemize}

To prove (a), we recall that by Theorem 4.1 in \cite{AGG}, there is a  $\mathbb{C}$-superalgebra isomorphism 
\begin{align*}
\psi: \mathfrak{U}\mathfrak{p}_n \rightarrow \mathfrak{U}_{\mathcal{A}}\mathfrak{p}_n/(q-1)\mathfrak{U}_{\mathcal{A}}\mathfrak{p}_n,
\end{align*} where $\mathcal{A}$ is the localization of $\mathbb{C}[q,q^{-1}]$ at the ideal generated by $q-1$, and $\mathfrak{U}_{\mathcal{A}}\mathfrak{p}_n$ is the $\mathcal{A}$-subalgebra of $\mathfrak{U}_q\mathfrak{p}_n$ generated by a set of elements $\tau_{ij}$ (for the precise definition of $\tau_{ij}$, see \S4 in \cite{AGG}). The map $\theta: \mathfrak{U}_{\mathcal{A}}\mathfrak{p}_n/(q-1)\mathfrak{U}_{\mathcal{A}}\mathfrak{p}_n \rightarrow \mathfrak{U}_{\mathbf{A}_1}/ \mathbf{A}_1\mathfrak{U}_{\mathbf{A}_1}$, defined by
\begin{align*}
&\theta(\overline{\tau}_{-i,-i-1}) \mapsto \overline{e_i}  && \theta(\overline{\tau}_{-i,i+1}) \mapsto \overline{e_{\overline{i}}}\\
&\theta(\overline{\tau}_{i,i+1}) \mapsto \overline{f_i} && \theta(\overline{\tau}_{i,-i-1}) \mapsto \overline{f_{\overline{i}}}\\
&\theta(\overline{\tau}_{i,-i}) \mapsto \overline{F_{\overline{i}}}  && \theta(\overline{\tau}_{ii}) \mapsto \overline{k}_i
\end{align*}
is also a  $\mathbb{C}$-superalgebra isomorphism.  Indeed, this follows from the definition of the corresponding generators and the fact that the classical limit of $t_{ij}$ and $\tau_{ij}$ coincide.  Also, we have already established that $\sigma: \mathfrak{U}_{\mathbf{A}_1}/\mathbf{A}_1\mathfrak{U}_{\mathbf{A}_1} \rightarrow U_1$ is a $\mathbb{C}$-superalgebra isomorphism by the definition of $U_1$. Therefore, the map
\begin{align*}
 \phi = \sigma\circ\theta\circ\psi: \mathfrak{U}\mathfrak{p}_n \longrightarrow U_1
\end{align*} is a  $\mathbb{C}$-superalgebra isomorphism.

To prove (b), let $w\in (V_{\mathbf{A}_1})_\mu$ and $h\in P^\vee$. Then we have that
\begin{align*}
(q^h; 0)_qw = \frac{q^h-1}{q-1}w = \frac{q^{\mu(h)}-1}{q-1}w.
\end{align*}
Taking the classical limit of both sides gives $\overline{h}\overline{w} = \mu(h)\overline{w}$, as desired.

It remains to prove (c). From  (b) we have that $\overline{h}\overline{v} = \lambda(h)\overline{v}$. Since $v$ is highest vector of $V_{\mathbf{A}_1}$ with highest weight $\lambda$, it follows that $\overline{e_{{i}}} \overline{v} = 0$ and $\overline{e_{\overline{i}}} \overline{v} = 0$ for each $i\in I$. Therefore, (a) and Proposition \ref{prop:highestweightV} imply that $V^1 = U_1^-\overline{v} = \mathfrak{U}\mathfrak{p}_n^-\overline{v}$. Hence, by definition, $V^1$ is a highest weight $\mathfrak{U}\mathfrak{p}_n$-module with highest weight $\lambda$ and highest weight vector $\overline{v}$.

\label{lem:q-symmetrizer}
For $\rho\in W_+$ and $\rho^\prime\in W_-$,
\begin{align*}
h(\rho)\mathsf{e}_+ &= \mathsf{e}_+h(\rho) = q^{\ell(\rho)}\mathsf{e}_+,\\
h(\rho^\prime)\mathsf{e}_- &= \mathsf{e}_-h(\rho^\prime) = (-q)^{-\ell(\rho^\prime)}\mathsf{e}_-.
\end{align*}

\label{thm-maximalvectors} Let $n$ and $k$ be positive integers such that $n\geq k$. Then
\begin{align*}
\{y_{\tau}\mathsf{c}_{\tilde{r},\tilde{s}}w_{\tau,\tilde{r},\tilde{s}} \mid (\tilde{r},\tilde{s})\in \mathcal{P}, \, \tau \in \mathsf{S}\mathsf{T}((\tilde{r} \cup \tilde{s})^c), \ell(\tau)\leq n\}
\end{align*}
is a linearly independent set of maximal vectors in the $\mathfrak{U}_q\mathfrak{p}_n$-module $V^{\otimes k}$.

Let $w = w_{\tau,\tilde{r},\tilde{s}}$ and $\theta = y_{\tau}\mathsf{c}_{\tilde{r},\tilde{s}}w$. Note that the weight of $\theta$ is the same as the weight of $w$ since $y_{\tau}c_{\tilde{r},\tilde{s}}$ commutes with the action of $\mathfrak{U}_q\mathfrak{p}_n$. Note that the fact that $\theta \neq 0$ and the linear independence property follow by applying the classical limit and using Theorem 3.8 in \cite{Mo}.


To show that $\theta$ is a maximal vector, it suffices to show that $\theta$ is annihilated by each root vector $e_{i}$ and $e_{\overline{i}}$, $i\in I$. The action of $e_{i}$ and $e_{\overline{i}}$ on $w$ can be explicitly written as follows
\begin{align}
\begin{split} \label{explict-uqpn-action}
e_{\overline{i}}(w_1\otimes\hdots\otimes w_k) &= \sum\limits_{a=1}^k (-1)^{p(w_1)+\hdots+p(w_{a-1})} q^{k_i}w_1\otimes\hdots\otimes q^{k_i}w_{a-1}\otimes e_{\overline{i}}w_{a}\otimes q^{k_{i+1}}w_{a+1}\otimes\hdots\otimes q^{k_{i+1}}w_k,\\
e_{i}(w_1\otimes\hdots\otimes w_k) &= \sum\limits_{a=1}^k  q^{k_i}w_1\otimes\hdots\otimes q^{k_i}w_{a-1}\otimes e_{i}w_{a}\otimes q^{k_{i+1}}w_{a+1}\otimes\hdots\otimes q^{k_{i+1}}w_k\\
- &\frac{q-q^{-1}}{2}\sum\limits_{\substack{a,b=1 \\ a < b}}^k (-1)^{p(w_1)+\hdots+p(w_{a-1})} q^{k_i}w_1\otimes\hdots\otimes q^{k_i}w_{a-1}\otimes e_{\overline{i}}w_{a}\otimes q^{k_{i+1}}w_{a+1}\otimes\hdots \\&\otimes q^{k_{i+1}}w_{b-1}\otimes F_{\overline{i+1}}w_{b}\otimes q^{k_{i+1}}w_{b+1}\otimes ...\otimes  q^{k_{i+1}}w_k.
\end{split} 
\end{align}

Let $x = e_i$ or $x= e_{\overline{i}}$. We  look at how  $x$ acts on $\mathsf{c}_{\tilde{r},\tilde{s}}w$.  Note that $\mathsf{c} V^{\otimes 2}$ is the trivial 
$\mathfrak{U}_q\mathfrak{p}_n$-module  $ \mathbb{C}(q)$. Therefore the sum of the terms with $x$ acting on a pair of contracted tensor factors is zero. Also, from \eqref{explict-uqpn-action}, we see that the action of $x$ on non-contracted tensor factors, or in other words where $w_i\in V_0$, those specific terms in the summation will be zero, except when $x=e_{j-1}$ for some $j\geq 2$. Thus $x$ either annihilates $\mathsf{c}_{\tilde{r},\tilde{s}}w$ or produces a sum of tensors which are obtained by applying $x = e_{j-1}$, for some $j\geq 2$, to a factor unaffected by $\mathsf{c}_{\tilde{r},\tilde{s}}$. Each of those tensors has one factor whose subscript is in $(\tilde{r} \cup \tilde{s})^c$ and has been lowered by one, so $u_j$ has been changed to $u_{j-1}$. Denote such a tensor by $\mathsf{v}$. We want to show that $y_\tau\mathsf{v} = 0$. 

Fix $\psi \in W_+$. There are two factors of the tensor $h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v}$ that have the same $u_j$. Then there exists a transposition $(a, b) = (\sigma_{-}^\tau) \rho\, (\sigma_{-}^\tau)^{-1} \in  (\sigma_{-}^\tau)W_-(\sigma_{-}^\tau)^{-1}$ which permutes these two factors. Using that $\ell (a,b) = \ell (\rho)$, we obtain
 $$ h(\sigma_{-}^\tau)\,h(\rho)\,h(\sigma_{-}^\tau)^{-1}\,h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v} = h(a,b)\,h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v} = q^{\ell(\rho)} h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v}.$$ 

By Lemma \ref{lem:q-symmetrizer}, we have that for $\rho\in W_-$,
\begin{align*}
(-q)^{-\ell(\rho)}\mathsf{e}_- = \mathsf{e}_- \, h(\rho) = \sum\limits_{\sigma\in W_-} (-q)^{-\ell(\sigma)}h(\sigma)\,h(\rho) 
\end{align*}
and hence
\begin{align*}
h(\sigma_{-}^\tau)\mathsf{e}_-\,h(\sigma_{-}^\tau)^{-1} = \sum\limits_{\sigma\in W_-} (-q)^{-\ell(\sigma)+\ell(\rho)}h(\sigma_{-}^\tau) \, h(\sigma)\, h(\sigma_{-}^\tau)^{-1}\, h(\sigma_{-}^\tau) \,h(\rho)\, h(\sigma_{-}^\tau)^{-1}
\end{align*}
Thus we have
\begin{align*}
h(\sigma_{-}^\tau)\mathsf{e}_-\,h(\sigma_{-}^\tau)^{-1}h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v} &= \sum\limits_{\sigma\in W_-} (-q)^{-\ell(\sigma)+\ell(\rho)}h(\sigma_{-}^\tau) \, h(\sigma)\, h(\sigma_{-}^\tau)^{-1}\, h(\sigma_{-}^\tau) \,h(\rho)\, h(\sigma_{-}^\tau)^{-1}h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v}\\
&= \sum\limits_{\sigma\in W_-} (-q)^{-\ell(\sigma)+\ell(\rho)}q^{\ell(\rho)} h(\sigma_{-}^\tau) \, h(\sigma)\, h(\sigma_{-}^\tau)^{-1}\, h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v}\\
&=  (-1)^{\ell(\rho)}q^{2\ell(\rho)}\sum\limits_{\sigma\in W_-}  (-q)^{-\ell(\sigma)} h(\sigma_{-}^\tau) \, h(\sigma)\, h(\sigma_{-}^\tau)^{-1}\,h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v}\\
&= (-1)^{\ell(\rho)}q^{2\ell(\rho)}h(\sigma_{-}^\tau)\mathsf{e}_-\,h(\sigma_{-}^\tau)^{-1}h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v}.
\end{align*}
Hence,  $$h(\sigma_{-}^\tau)\mathsf{e}_-\,h(\sigma_{-}^\tau)^{-1}h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v} = 0$$ for each $\psi \in W_+$. Therefore, we have that
\begin{align*}
 h(\sigma_{-}^\tau)\mathsf{e}_-\,h(\sigma_{-}^\tau)^{-1}h(\sigma_{+}^\tau)\mathsf{e}_+\,h(\sigma_{+}^\tau)^{-1}\mathsf{v} = \sum\limits_{\psi\in W_+} q^{\ell(\psi)}h(\sigma_{-}^\tau)\mathsf{e}_-\,h(\sigma_{-}^\tau)^{-1}h(\sigma_{+}^\tau)h(\psi)h(\sigma_{+}^\tau)^{-1}\mathsf{v} = 0.
\end{align*} This concludes the proof of $y_\tau\mathsf{v} = 0$.

\label{y1-2-V2-red-indecomposable} The module $y_{\ytableaushort{1,2}}V^{\otimes 2}$ is reducible and indecomposable. More precisely, there is a non-split exact sequence of  $\mathfrak{U}_q \mathfrak{p}_n$-modules 
\begin{equation} \label{eq-seq1}
0 \longrightarrow V^q(\epsilon_1 + \epsilon_2)\longrightarrow y_{\ytableaushort{1,2}}V^{\otimes 2} \longrightarrow V^q(0) \longrightarrow 0.
\end{equation}

\label{y12-V2-red-indecomposable} The module $y_{\ytableaushort{12}}V^{\otimes 2}$ is reducible and indecomposable. More precisely, there is a non-split short exact sequences of $\mathfrak{U}_q \mathfrak{p}_n$-modules 
\begin{equation} \label{eq-seq2}
0 \longrightarrow V^q(0) \longrightarrow y_{\ytableaushort{12}}V^{\otimes 2} \longrightarrow V^q(2\epsilon_1) \longrightarrow 0.
\end{equation}

\label{uqpn-2tensorproductdecomposition}  As a $\mathfrak{U}_q\mathfrak{p}_n$-module, we have the following decomposition
\begin{align*}
\ytableausetup
{smalltableaux}
V^{\otimes 2} = y_{\ytableaushort{12}}V^{\otimes 2} \oplus  y_{\ytableaushort{1,2}}V^{\otimes 2},
\end{align*}
where the submodules in the above decomposition are involved in the non-split short exact sequences \eqref{eq-seq1}, \eqref{eq-seq2}.

Let $T: V^{\otimes 2} \longrightarrow  V^{\otimes 2}$ be the $\mathfrak{U}_q\mathfrak{p}_n$-module homomorphism defined by $$T(v) = y_{\ytableaushort{12}}v.$$  Note that $$y_{\ytableaushort{12}}y_{\ytableaushort{1,2}} = \frac{1}{(1+q^2)(1+q^{-2})}(1+qt_1)(1-q^{-1}t_1) = 0.$$ So, we have that $ y_{\ytableaushort{1,2}}V^{\otimes 2} \subset \ker T$, which implies that  $ y_{\ytableaushort{1,2}}V^{\otimes 2} = \ker T$ since the only maximal vector of $V^{\otimes 2}$ in $\ker T$ is $\theta_2^q$. Thus we have a short exact sequence
\begin{align*}
0 \longrightarrow y_{\ytableaushort{1,2}}V^{\otimes 2} \longrightarrow V^{\otimes 2}\longrightarrow  y_{\ytableaushort{12}}V^{\otimes 2} \longrightarrow 0.
\end{align*}
Using the embedding $\iota: y_{\ytableaushort{12}} V^{\otimes 2} \longrightarrow  V^{\otimes 2}$ and that $T  \circ  \iota= \mathrm{id}$, we see that the sequence above splits. The remaining part of the theorem follows from Propositions \ref{y1-2-V2-red-indecomposable} and \ref{y12-V2-red-indecomposable}.

\label{prop-y1/2/3} The module $y_{\ytableaushort{1,2,3}}V^{\otimes 3}$ is reducible and indecomposable. More precisely, we have the following non-split short exact sequence
\begin{equation} \label{eq-ne3-1}
0 \longrightarrow V^q(\epsilon_1 + \epsilon_2 + \epsilon_3)\longrightarrow  y_{\ytableaushort{1,2,3}}V^{\otimes 3} \longrightarrow V^q(\epsilon_1) \longrightarrow 0.
\end{equation}

\label{prop-y123} The module $y_{\ytableaushort{123}}V^{\otimes 3}$ is reducible and indecomposable. More precisely, we have the following non-split short exact sequence
\begin{equation} \label{eq-ne3-2}
0 \longrightarrow V^q(\epsilon_1) \longrightarrow  y_{\ytableaushort{123}}V^{\otimes 3} \longrightarrow V^q(3\epsilon_1) \longrightarrow 0.
\end{equation}

\label{prop-y12/3} The module $y_{\ytableaushort{12,3}}V^{\otimes 3}$ is completely reducible as a $\mathfrak{U}_q\mathfrak{p}_n$-module into a direct sum of irreducible $\mathfrak{U}_q\mathfrak{p}_n$-modules. More precisely, we have the following split short exact sequence
\begin{equation} \label{eq-ne3-3}
0 \longrightarrow V^q(2\epsilon_1 + \epsilon_2)\longrightarrow  y_{\ytableaushort{12,3}}V^{\otimes 3} \longrightarrow V^q(\epsilon_1) \longrightarrow 0.
\end{equation}

Consider the $\mathfrak{U}_q\mathfrak{p}_n$-module homomorphism $T: y_{\ytableaushort{12,3}}V^{\otimes 3}  \rightarrow \mathsf{c}_2V^{\otimes 3}$ such that $T(y_{\ytableaushort{12,3}}v) = \mathsf{c}_2y_{\ytableaushort{12,3}}v$. Since $$\mathsf{c}_2 y_{\ytableaushort{12,3}}\mathsf{c}_2 = \frac{q^{-2}}{q^{2}+1+q^{-2}}\mathsf{c}_2,$$ we have that $T$ is surjective and $$\mathsf{c}_2y_{\ytableaushort{12,3}}V^{\otimes 3} = \mathsf{c}_2V^{\otimes 3}.$$ 
Note that $$y_{\ytableaushort{12,3}}\mathsf{c}_2(u_1\otimes u_1\otimes u_{-1}) = -\theta_1^q - (q-q^{-1})\theta_2^q + \theta_3^q. $$ Thus, $ -\theta_1^q - (q-q^{-1})\theta_2^q + \theta_3^q\in y_{\ytableaushort{12,3}}\mathsf{c}_2V^{\otimes 3}$. However,  $u_1\otimes u_1\otimes  u_2 \not\in \mathsf{c}_2V^{\otimes 3}$, which implies that $\theta^q_5\in y_{\ytableaushort{12,3}}\mathsf{c}_2V^{\otimes 3}$. So, by Proposition \ref{prop-max-3}, we have that $$ V^q(\epsilon_1)\cong \mathfrak{U}_q\mathfrak{p}_n\big(-\theta_1^q - (q-q^{-1})\theta_2^q + \theta_3^q\big) = y_{\ytableaushort{12,3}}\mathsf{c}_2V^{\otimes 3} .$$ Since $\mathsf{c}_2V^{\otimes 3} \cong V^q(\epsilon_1)$, we have an inclusion map $i: \mathsf{c}_2V^{\otimes 3} \rightarrow y_{\ytableaushort{12,3}}V^{\otimes 3} $ such that $i\circ T = \text{id}$. Therefore, the following short exact sequence splits:
\begin{align*}
0 \longrightarrow \ker T \longrightarrow y_{\ytableaushort{12,3}}V^{\otimes 3} \xlongrightarrow{T} \mathsf{c}_2V^{\otimes 3} \longrightarrow 0
\end{align*}
By Proposition \ref{prop-max-3}, since $\theta_5^q\in \ker T$, we have that $\ker T = \mathfrak{U}_q\mathfrak{p}_n\theta_5^q \cong V^q(2\epsilon_1 + \epsilon_2)$. This implies the exact sequence \eqref{eq-ne3-3}.

\label{prop-y13/2} The module $y_{\ytableaushort{13,2}}V^{\otimes 3}$ is isomorphic to $y_{\ytableaushort{12,3}}V^{\otimes 3}$ as $\mathfrak{U}_q\mathfrak{p}_n$-modules.  More precisely, we have the following split short exact sequence
\begin{equation} \label{eq-ne3-4}
0 \longrightarrow V^q(2\epsilon_1 + \epsilon_2)\longrightarrow  y_{\ytableaushort{13,2}}V^{\otimes 3} \longrightarrow V^q(\epsilon_1) \longrightarrow 0.
\end{equation}

\label{uqpn-3tensorproductdecomposition}  As a $\mathfrak{U}_q\mathfrak{p}_n$-module, we have the following decomposition

\begin{align} \label{eq-v3-decomposition}
V^{\otimes 3} = y_{\ytableaushort{123}}V^{\otimes 3} \oplus  y_{\ytableaushort{12,3}}V^{\otimes 3} \oplus  y_{\ytableaushort{13,2}}V^{\otimes 3} \oplus  y_{\ytableaushort{1,2,3}}V^{\otimes 3},
\end{align}
where each submodule in the above decomposition are involved in either the non-split short exact sequences \eqref{eq-ne3-1} and \eqref{eq-ne3-2}, or in the split short exact sequences \eqref{eq-ne3-3} and \eqref{eq-ne3-4}.

Let $T: V^{\otimes 3} \longrightarrow  V^{\otimes 3}$ be the $\mathfrak{U}_q\mathfrak{p}_n$-module homomorphism defined by $$T(v) = y_{\ytableaushort{123}}v.$$  Note that $$y_{\ytableaushort{123}}\mathsf{K} =  0,$$ where $\mathsf{K} = y_{\ytableaushort{12,3}} , y_{\ytableaushort{13,2}},  y_{\ytableaushort{1,2,3}} $. By Proposition \ref{prop-max-3}, this implies that $-\theta_1^q - (q-q^{-1})\theta_2^q + \theta_3^q , -q\theta_2^q + \theta_3^q, \theta_q^5, \theta_q^6, \theta_q^7\in \ker T$. We have the short exact sequence
\begin{align*}
0 \longrightarrow \ker T \longrightarrow V^{\otimes 3}\longrightarrow  y_{\ytableaushort{123}}V^{\otimes 3} \longrightarrow 0.
\end{align*}
Using the embedding $\iota: y_{\ytableaushort{123}} V^{\otimes 3} \longrightarrow  V^{\otimes 3}$ and that $T  \circ  \iota= \mathrm{id}$, we see that the sequence above splits. 

Let $T^\prime: \ker T \longrightarrow  \ker T$ be the $\mathfrak{U}_q\mathfrak{p}_n$-module homomorphism defined by $$T(v) = y_{\ytableaushort{12,3}}v.$$  Note that $$y_{\ytableaushort{12,3}}\mathsf{K} =  0,$$ where $\mathsf{K} = y_{\ytableaushort{13,2}},  y_{\ytableaushort{1,2,3}} $. By Proposition \ref{prop-max-3}, this implies that $ -q\theta_2^q + \theta_3^q, \theta_q^6, \theta_q^7\in \ker T^\prime$. Using the embedding $\iota^\prime: y_{\ytableaushort{12,3}} V^{\otimes 3} \longrightarrow  V^{\otimes 3}$ and that $T^\prime  \circ  \iota^\prime = \mathrm{id}$, we see that the short exact sequence \begin{align*}
0 \longrightarrow \ker T^\prime \longrightarrow \ker T \longrightarrow  y_{\ytableaushort{12, 3}}V^{\otimes 3} \longrightarrow 0.
\end{align*}
 splits. Using similar arguments, we have that $\ker T^\prime = y_{\ytableaushort{13,2}}V^{\otimes 3} \oplus y_{\ytableaushort{1,2,3}} V^{\otimes 3}$, and thus the decomposition \eqref{eq-v3-decomposition} follows.

The remaining part of the theorem follows from Propositions \ref{prop-y1/2/3}, \ref{prop-y123}, \ref{prop-y12/3}, and \ref{prop-y13/2}.
